import React from 'react';

const Projects = () => {
    const sectionStyle = {
        padding: '2rem',
        backgroundColor: '#f9f9f9',
        fontFamily: 'Arial, sans-serif',
        lineHeight: '1.6',
    };

    const headingStyle = {
        fontSize: '2.5rem',
        color: '#333',
        textAlign: 'center',
        marginBottom: '2rem',
    };

    const projectListStyle = {
        listStyleType: 'none',
        padding: '0',
        margin: '0 auto',
        maxWidth: '800px',
    };

    const projectItemStyle = {
        backgroundColor: '#fff',
        borderRadius: '8px',
        boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
        padding: '1.5rem',
        marginBottom: '1.5rem',
        transition: 'transform 0.2s',
    };

    const projectItemHoverStyle = {
        transform: 'scale(1.02)',
    };

    const projectTitleStyle = {
        fontSize: '1.8rem',
        color: '#007bff',
        marginBottom: '0.5rem',
    };

    const projectDescriptionStyle = {
        fontSize: '1.2rem',
        color: '#555',
        marginBottom: '0.5rem',
    };

    const projectTechStyle = {
        fontSize: '1rem',
        color: '#777',
    };

    return (
        <section style={sectionStyle}>
            <h1 style={headingStyle}>Projects</h1>
            <ul style={projectListStyle}>
                <li
                    style={projectItemStyle}
                    onMouseOver={(e) => (e.currentTarget.style.transform = projectItemHoverStyle.transform)}
                    onMouseOut={(e) => (e.currentTarget.style.transform = 'none')}
                >
                    <h2 style={projectTitleStyle}>Java Calculator</h2>
                    <p style={projectDescriptionStyle}>Description: Basic object-oriented programming (OOP) concepts are demonstrated by this Java-based calculator. The calculator's classes, which contain fundamental operations like addition, subtraction, multiplication, and division, are designed to be both simple and functional. To encourage modularity and code reuse, each operation is implemented as a method inside its corresponding class. Simple arithmetic computations can be performed with ease thanks to the user interface. This project is a great resource for novice Java programmers as it provides a hands-on introduction to OOP concepts like encapsulation, inheritance, and polymorphism.</p>
                    <p style={projectTechStyle}>Language: Java</p>
                </li>
                <li
                    style={projectItemStyle}
                    onMouseOver={(e) => (e.currentTarget.style.transform = projectItemHoverStyle.transform)}
                    onMouseOut={(e) => (e.currentTarget.style.transform = 'none')}
                >
                    <h2 style={projectTitleStyle}>Java BMI Calculator</h2>
                    <p style={projectDescriptionStyle}>Description: This Java-based BMI calculator demonstrates fundamental object-oriented programming (OOP) concepts. By entering their height in meters and weight in kilograms, users can use the formula BMI = weight / (height * height) to determine their Body Mass Index (BMI). The application has a straightforward user interface and encapsulates functions like processing user input and carrying out calculations using classes. This project encourages code organization and reuse while providing a great introduction to Java programming and OOP principles for novices by utilizing OOP ideas like encapsulation and modularity.</p>
                    <p style={projectTechStyle}>Language: Java</p>
                </li>
            </ul>
        </section>
    );
};

export default Projects;
